512	import org.springframework.security.authentication.AuthenticationManager;
513	import org.springframework.security.config.annotation.authentication.builders.AuthenticationManagerBuilder;
514	import org.springframework.security.config.annotation.method.configuration.EnableGlobalMethodSecurity;
515	import org.springframework.security.config.annotation.web.builders.HttpSecurity;
516	import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
517	import org.springframework.security.config.annotation.web.configuration.WebSecurityConfigurerAdapter;
518	import org.springframework.security.config.http.SessionCreationPolicy;
519	import org.springframework.security.core.userdetails.UserDetailsService;
520	import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
521	import org.springframework.security.crypto.password.PasswordEncoder;
522	
523	import javax.servlet.http.HttpServletResponse;
524	
525	/**
526	 * Security configuration using the deprecated WebSecurityConfigurerAdapter.
527	 * This needs to be migrated to component-based security configuration in Spring Security 6.
528	 */
529	@Configuration
530	@EnableWebSecurity
531	@EnableGlobalMethodSecurity(prePostEnabled = true)
532	public class SecurityConfig extends WebSecurityConfigurerAdapter {
533	
534	    @Autowired
535	    private UserDetailsService userDetailsService;
536	
537	    @Bean
538	    public PasswordEncoder passwordEncoder() {
539	        return new BCryptPasswordEncoder();
540	    }
541	
542	    @Override
543	    protected void configure(AuthenticationManagerBuilder auth) throws Exception {
544	        auth.userDetailsService(userDetailsService)
545	            .passwordEncoder(passwordEncoder());
546	    }
547	
548	    @Override
549	    @Bean
550	    public AuthenticationManager authenticationManagerBean() throws Exception {
551	        return super.authenticationManagerBean();
552	    }
553	
554	    @Override
555	    protected void configure(HttpSecurity http) throws Exception {
556	        http
557	            .csrf().disable()
558	            .sessionManagement()
559	                .sessionCreationPolicy(SessionCreationPolicy.STATELESS)
560	            .and()
561	            .exceptionHandling()
562	                .authenticationEntryPoint((request, response, ex) -> {
563	                    response.sendError(HttpServletResponse.SC_UNAUTHORIZED, ex.getMessage());
564	                })
565	            .and()
566	            .authorizeRequests()
567	                // Public endpoints
568	                .antMatchers(HttpMethod.POST, "/api/users").permitAll()
569	                .antMatchers("/api/auth/**").permitAll()
570	                .antMatchers("/h2-console/**").permitAll()
571	                .antMatchers("/actuator/health").permitAll()
572	                // All other endpoints require authentication
573	                .anyRequest().authenticated()
574	            .and()
575	            .headers().frameOptions().disable(); // For H2 console
576	    }
