586	 * Component for custom security expressions used in @PreAuthorize annotations.
587	 */
588	@Component("userSecurity")
589	public class UserSecurity {
590	
591	    /**
592	     * Check if the current authenticated user is the owner of the resource.
593	     * This is used in @PreAuthorize expressions like @userSecurity.isOwner(#id)
594	     */
595	    public boolean isOwner(Long userId) {
596	        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
597	        if (authentication == null || !authentication.isAuthenticated()) {
598	            return false;
599	        }
600	
601	        // Get the username from the authentication principal
602	        String currentUsername = authentication.getName();
603	
604	        // In a real application, you would check if the userId belongs to the current user
605	        // For simplicity, we're checking if the authentication name matches a user ID pattern
606	        // This should be replaced with actual user ID lookup logic
607	        return currentUsername != null && currentUsername.equals(userId.toString());
608	    }
609	}
